function status(s){$('status').textContent=s;}
async function work(fn){if(busy)return;busy=true;$('office').disabled=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){status(e.message||String(e));}finally{busy=false;$('office').disabled=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);updateEditStatus();}}
function visibleRows(){return data?data.rows.filter(r=>r.group===$('kind').value&&!r.excluded):[];}
function idwPower(){return Math.max(.1,Math.min(8,Number($('power').value)||6));}
function neighborCount(){return Math.max(3,Math.min(64,Number($('neighbors').value)||12));}
function updateEditStatus(){const n=removedReports.length;$('editStatus').textContent=n+' report'+(n===1?'':'s')+' removed from this loaded map.';$('undoRemoval').disabled=!n;$('restoreReports').disabled=!n;}
function removeReport(id){const r=data?.rows.find(r=>r.id===id);if(!r||r.excluded)return;r.excluded=true;removedReports.push(r);selected=null;$('editor').hidden=true;updateEditStatus();renderList();draw();}
