 // Sample at up to 512 columns to keep contour redraws responsive.
 const stride=Math.max(1,Math.ceil(field.width/512)),gx=[],gy=[];for(let x=0;x<field.width;x+=stride)gx.push(x);if(gx.at(-1)!==field.width-1)gx.push(field.width-1);for(let y=0;y<field.height;y+=stride)gy.push(y);if(gy.at(-1)!==field.height-1)gy.push(field.height-1);
