async function scanOfficeProducts(autoLoad=false){
 const office=officeCode();updateOfficeSource();$('url').value=sourceUrl(office);loadOfficeMap(office);
 renderToken++;fillBuild=null;fillKey='';data=null;fillField=null;clearContours();renderPshVariables();removedReports=[];updateEditStatus();selected=null;points.clearLayers();if(overlay){map.removeLayer(overlay);overlay=null;}canvas=null;$('reports').innerHTML='';$('title').textContent='';$('legend').innerHTML='';$('kind').innerHTML='';$('editor').hidden=true;scannedProducts=[];
 $('metadataStatus').textContent='Scanning retained PNS products for metadata…';$('scanStatus').textContent='Getting '+office+' PNS versions…';
 const listing=await call('getPnsVersions',office);
 for(let i=0;i<listing.versions.length;i+=8){const part=await call('scanPnsBatch',office,listing.versions.slice(i,i+8));scannedProducts.push(...part);updateProductList();$('scanStatus').textContent='Scanned '+scannedProducts.length+'/'+listing.versions.length+' PNS products…';}
 const good=scannedProducts.filter(p=>p.count>0).length;$('scanStatus').textContent=office+': '+scannedProducts.length+' retained PNS products; '+good+' have valid plottable metadata.';
 $('metadataStatus').classList.toggle('missing',!good);$('metadataStatus').textContent=good?'Choose a metadata-ready PNS above, then Load chosen PNS.':'No retained PNS contains supported valid metadata. You can still paste supplemental metadata at the bottom.';status('Office scan complete.');
 if(autoLoad){const latest=scannedProducts.filter(p=>p.count>0&&!p.error).sort((a,b)=>a.version-b.version)[0];const version=latest?latest.version:1;$('availablePns').value=String(version);$('url').value=sourceUrl(office,version);status('Loading newest '+(latest?'metadata-ready ':'')+'PNS…');accept(await call('fetchPns',$('url').value));}
}
$('scanOffice').onclick=()=>work(()=>scanOfficeProducts());
$('refreshPns').onclick=()=>work(()=>scanOfficeProducts(true));
$('loadAvailable').onclick=()=>work(async()=>{
 const office=officeCode(),v=Number($('availablePns').value),p=scannedProducts.find(p=>p.version===v);if(!p)throw Error('Scan the office and choose an available PNS first.');
 $('url').value=sourceUrl(office,v);const d=await call('fetchPns',$('url').value);
 if(p.signature&&signatureClient(d.text)!==p.signature)throw Error('The selected version shifted to a different issuance since the scan. Scan again to refresh the list.');accept(d);
});
function signatureClient(text){return (text.match(/^\s*[A-Z]{4}\d{2}\s+[A-Z]{4}\s+\d{6}[^\n]*/m)||[''])[0].trim()+'|'+(text.match(/^.*(?:AM|PM)\s+[A-Z]{2,4}.*$/m)||[''])[0].trim();}
$('office').onchange=()=>{$('availablePns').innerHTML='<option value="">Scan this office first</option>';scannedProducts=[];try{updateOfficeSource();$('url').value=sourceUrl(officeCode());$('scanOffice').click();}catch(e){status(e.message);}};
updateOfficeSource();$('scanOffice').click();
